import{_ as e,c as l,o as t,af as r}from"./chunks/framework.CI8A52oi.js";const s=JSON.parse('{"title":"updatelog","description":"","frontmatter":{},"headers":[],"relativePath":"updatelog.md","filePath":"updatelog.md"}'),i={name:"updatelog.md"};function p(o,a,h,b,n,c){return t(),l("div",null,[...a[0]||(a[0]=[r(`<h1 id="updatelog" tabindex="-1">updatelog <a class="header-anchor" href="#updatelog" aria-label="Permalink to “updatelog”">​</a></h1><p><strong>服务器更新摘要</strong>⎛⎝≥⏝⏝≤⎛⎝<strong>：</strong></p><h1 id="一周目" tabindex="-1">一周目 <a class="header-anchor" href="#一周目" aria-label="Permalink to “一周目”">​</a></h1><p>现在是RWP时期（</p><h2 id="_1-18-1" tabindex="-1">1.18.1： <a class="header-anchor" href="#_1-18-1" aria-label="Permalink to “1.18.1：”">​</a></h2><h3 id="beta1-1" tabindex="-1">beta1.1 <a class="header-anchor" href="#beta1-1" aria-label="Permalink to “beta1.1”">​</a></h3><p>一次重大更新，更新到1.18.1</p><h3 id="beta1-1-1-1" tabindex="-1">beta1.1.1.1 <a class="header-anchor" href="#beta1-1-1-1" aria-label="Permalink to “beta1.1.1.1”">​</a></h3><p>迁移了/menu 为 /mainmenu ；更新了计分板</p><h3 id="beta1-1-2" tabindex="-1">beta1.1.2 <a class="header-anchor" href="#beta1-1-2" aria-label="Permalink to “beta1.1.2”">​</a></h3><p>更新了image插件（地图画回来了）</p><h3 id="beta1-1-3" tabindex="-1">beta1.1.3 <a class="header-anchor" href="#beta1-1-3" aria-label="Permalink to “beta1.1.3”">​</a></h3><h4 id="beta1-1-3-0" tabindex="-1">beta1.1.3.0 <a class="header-anchor" href="#beta1-1-3-0" aria-label="Permalink to “beta1.1.3.0”">​</a></h4><p>换回PAPER 核心 调整内存为6G</p><h4 id="beta1-1-3-1" tabindex="-1">beta1.1.3.1 <a class="header-anchor" href="#beta1-1-3-1" aria-label="Permalink to “beta1.1.3.1”">​</a></h4><p>回归了飞行 kit礼包</p><h3 id="beta1-1-4" tabindex="-1">beta1.1.4 <a class="header-anchor" href="#beta1-1-4" aria-label="Permalink to “beta1.1.4”">​</a></h3><p>调整了服务器备份时间为7:00 13:00 18:00 00:00</p><p>这更新多逝一件美逝（a bushi）</p><h3 id="beta1-1-5" tabindex="-1">beta1.1.5 <a class="header-anchor" href="#beta1-1-5" aria-label="Permalink to “beta1.1.5”">​</a></h3><h4 id="beta1-1-5-0" tabindex="-1">beta1.1.5.0 <a class="header-anchor" href="#beta1-1-5-0" aria-label="Permalink to “beta1.1.5.0”">​</a></h4><p>调整怪物生成的最高亮度为7；平滑客户端区块加载</p><h4 id="beta1-1-5-1" tabindex="-1">beta1.1.5.1 <a class="header-anchor" href="#beta1-1-5-1" aria-label="Permalink to “beta1.1.5.1”">​</a></h4><p>更改了出生点为主世界；调整骷髅马概率</p><h4 id="beta1-1-5-2" tabindex="-1">beta1.1.5.2 <a class="header-anchor" href="#beta1-1-5-2" aria-label="Permalink to “beta1.1.5.2”">​</a></h4><p>关闭了服务器数据包压缩; 上调了了怪物生成速度</p><h3 id="fixbeta1-1-6" tabindex="-1">fixbeta1.1.6 <a class="header-anchor" href="#fixbeta1-1-6" aria-label="Permalink to “fixbeta1.1.6”">​</a></h3><h4 id="fixbeta1-1-6-0" tabindex="-1">fixbeta1.1.6.0 <a class="header-anchor" href="#fixbeta1-1-6-0" aria-label="Permalink to “fixbeta1.1.6.0”">​</a></h4><p>找到区块无法加载的原因，并进行了临时修复</p><h4 id="beta1-1-6-1" tabindex="-1">beta1.1.6.1 <a class="header-anchor" href="#beta1-1-6-1" aria-label="Permalink to “beta1.1.6.1”">​</a></h4><p>调整了AFK判定和机制，挂机后会停止周围生物</p><h3 id="upbeta-1-2-1" tabindex="-1">upbeta 1.2.1 <a class="header-anchor" href="#upbeta-1-2-1" aria-label="Permalink to “upbeta 1.2.1”">​</a></h3><p>升级内存至16G（分配13G），回归了网页地图</p><h3 id="beta1-2-2" tabindex="-1">beta1.2.2 <a class="header-anchor" href="#beta1-2-2" aria-label="Permalink to “beta1.2.2”">​</a></h3><p>开启了网络压缩，优化了服务器JVM启动参数</p><h3 id="beta1-2-3" tabindex="-1">beta1.2.3 <a class="header-anchor" href="#beta1-2-3" aria-label="Permalink to “beta1.2.3”">​</a></h3><p>解决了区块加载过慢的问题，但这对低配玩家不是一件好事</p><h3 id="beta-1-2-4" tabindex="-1">beta 1.2.4 <a class="header-anchor" href="#beta-1-2-4" aria-label="Permalink to “beta 1.2.4”">​</a></h3><h4 id="beta-1-2-4-0" tabindex="-1">beta 1.2.4.0 <a class="header-anchor" href="#beta-1-2-4-0" aria-label="Permalink to “beta 1.2.4.0”">​</a></h4><p>提高了光照线程上限，现在大型轰炸应该有很好的表现</p><h4 id="beta-1-2-4-1" tabindex="-1">beta 1.2.4.1 <a class="header-anchor" href="#beta-1-2-4-1" aria-label="Permalink to “beta 1.2.4.1”">​</a></h4><p>在计分板上加入了CPU使用率</p><h3 id="beta-1-2-5" tabindex="-1">beta 1.2.5 <a class="header-anchor" href="#beta-1-2-5" aria-label="Permalink to “beta 1.2.5”">​</a></h3><h4 id="beta-1-2-5-0" tabindex="-1">beta 1.2.5.0 <a class="header-anchor" href="#beta-1-2-5-0" aria-label="Permalink to “beta 1.2.5.0”">​</a></h4><p>加入了聊天前缀，在/mainmenu 的左下角可切换</p><h4 id="beta-1-2-5-1" tabindex="-1">beta 1.2.5.1 <a class="header-anchor" href="#beta-1-2-5-1" aria-label="Permalink to “beta 1.2.5.1”">​</a></h4><p>更改了保存速度和间隔（10min），平滑保存占用</p><h4 id="beta-1-2-5-2" tabindex="-1">beta 1.2.5.2 <a class="header-anchor" href="#beta-1-2-5-2" aria-label="Permalink to “beta 1.2.5.2”">​</a></h4><p>增加了TNT爆炸上限，解决了三向轰炸机的TNT堆叠问题</p><h4 id="beta-1-2-5-3" tabindex="-1">beta 1.2.5.3 <a class="header-anchor" href="#beta-1-2-5-3" aria-label="Permalink to “beta 1.2.5.3”">​</a></h4><p>增加了发包限制的上限</p><h3 id="beta-1-2-6" tabindex="-1">beta 1.2.6 <a class="header-anchor" href="#beta-1-2-6" aria-label="Permalink to “beta 1.2.6”">​</a></h3><p>增加了生物的生成上线，相较于之前提升70%</p><h3 id="beta-1-2-7" tabindex="-1">beta 1.2.7 <a class="header-anchor" href="#beta-1-2-7" aria-label="Permalink to “beta 1.2.7”">​</a></h3><p>略微减少了生成上限，增加了服务器运算距离，增加了实体显示距离，增加了/dback /back 的冷却时间，物品消失时间恢复为原版，平滑动物和怪物的AI加载，调整了 lagging时村民的AI强度</p><h3 id="beta-1-2-8" tabindex="-1">beta 1.2.8 <a class="header-anchor" href="#beta-1-2-8" aria-label="Permalink to “beta 1.2.8”">​</a></h3><p>增加了服务器的simulation改为 14*14（原版12*12）</p><h3 id="beta-2-0" tabindex="-1">Beta 2.0 <a class="header-anchor" href="#beta-2-0" aria-label="Permalink to “Beta 2.0”">​</a></h3><blockquote><p>升级了服务器的后台MCSM至9.2的版本</p></blockquote><blockquote><p>服务器升级到了群组服，群组核心从BC转换到了Velocity核心</p></blockquote><blockquote><p>服务器数量有单机提升至双机，云服务器加物理服务器的组合</p></blockquote><blockquote><p>LuckPerms 和 CoreProctet 的数据存储类型转换到了MySQL</p></blockquote><blockquote><p>服务器测试性地加入了小游戏-BedWar , 预计2.8会放到云服务器上</p></blockquote><blockquote><p>更新了服务器后台的背景图层为随机图片</p></blockquote><blockquote><p>修复了末地刷沙机无法正常工作的BUG（好像一直没修好？？！）</p></blockquote><blockquote><p>提升了Velocity的内存占用率，榨干每一点内存</p></blockquote><blockquote><p>对主服务器（生存服）配置进行了中小幅度调整 ,提升玩家的体验</p></blockquote><blockquote><p>加入tab插件（）并且调整了tab的形式，由于更新导致tab十分潦草</p></blockquote><blockquote><p>更换了tab的插件并且还原了beta1.0的原始外观，可太难了我</p></blockquote><blockquote><p>现在玩家挂机时会在名字后面加入[AFK]的提示，非常银杏化</p></blockquote><blockquote><p>由于服务器动辄100G的大小，备份时间改为每天凌晨1：00</p></blockquote><h3 id="beta-2-1" tabindex="-1">Beta 2.1 <a class="header-anchor" href="#beta-2-1" aria-label="Permalink to “Beta 2.1”">​</a></h3><p>降低了区块的加载速度，平滑区块加载，新增网页3D地图（Bluemap），略微下调了生物生成上线，略微下调了生物活动范围，大幅上调了区块保留时间，关闭了同步区块读写</p><h3 id="beta-2-2" tabindex="-1">Beta 2.2 <a class="header-anchor" href="#beta-2-2" aria-label="Permalink to “Beta 2.2”">​</a></h3><h4 id="beta-2-2-0" tabindex="-1">Beta 2.2.0 <a class="header-anchor" href="#beta-2-2-0" aria-label="Permalink to “Beta 2.2.0”">​</a></h4><p>更换了小游戏服的系统，大幅提高了稳定性，纠正了之前错 误填写运算距离的参数</p><p>现在下调回6，降低了生物的生成速度（并未降低怪物），提高了所有实体的活动（</p><p>AI触发） 距离，重新调整了实体的软、强消失距离，调整了实体挤压次数，删除了</p><p>对村民的调整</p><blockquote><p>此次的参考文档：</p></blockquote><blockquote><p><a href="https://github.com/YouHaveTrouble/minecraft-optimization" target="_blank" rel="noreferrer">https://github.com/YouHaveTrouble/minecraft-optimization</a></p></blockquote><blockquote><p>承诺以服务器实际情况动态调整优化</p></blockquote><h4 id="beta-2-2-1" tabindex="-1">Beta 2.2.1 <a class="header-anchor" href="#beta-2-2-1" aria-label="Permalink to “Beta 2.2.1”">​</a></h4><p>调整了汉化文件中出现的错误，开启了Bluemap中的地标</p><h3 id="beta-2-3" tabindex="-1">Beta 2.3 <a class="header-anchor" href="#beta-2-3" aria-label="Permalink to “Beta 2.3”">​</a></h3><p>我也忘记了更新了什么</p><h3 id="beta-2-4" tabindex="-1">Beta 2.4 <a class="header-anchor" href="#beta-2-4" aria-label="Permalink to “Beta 2.4”">​</a></h3><h4 id="beta-2-4-0" tabindex="-1">Beta 2.4.0 <a class="header-anchor" href="#beta-2-4-0" aria-label="Permalink to “Beta 2.4.0”">​</a></h4><p>改变了子服务器bedwar 为 pure</p><p>将main和pure 的聊天进行了互通</p><p>更改了Tab 稍微调整了下布局</p><p>预计加入power 子服务器用于RPG游戏</p><p>删除BlueMap 插件，这意味着网页地图将失效</p><p>稍微改了下McMod上的介绍排版</p><h4 id="_2-4-3" tabindex="-1">2.4.3： <a class="header-anchor" href="#_2-4-3" aria-label="Permalink to “2.4.3：”">​</a></h4><p>增加子服务器rand（真的只是用来凑个数</p><p>修改了tab的布局，增加了部分参数，解决了变量不显的bug</p><p>更改了子服连接的密钥（这个不用管</p><p>更改了pure的各建筑的生成种子（未更改史莱姆区块的</p><p>降低了rand服务器的带宽占用（并没有什么用</p><p>彻底删除了main的BlueMap （150G的小文件啊~~</p><blockquote><p><strong>原腐竹RedWhite因考试将腐竹身份转移至欧阳远怡</strong></p></blockquote><blockquote><p><strong>CBW为代理腐竹</strong></p></blockquote><blockquote><p><s>（实际上还是hu这个屑逼在维护大部分东西）（悲催打工人）</s></p></blockquote><h1 id="二周目" tabindex="-1">二周目 <a class="header-anchor" href="#二周目" aria-label="Permalink to “二周目”">​</a></h1><blockquote><p>将服务器移至云端</p></blockquote><blockquote><p>将服务器更为creative RedT(main) BedWar</p></blockquote><h2 id="beta-3-0-0" tabindex="-1">beta 3.0.0 <a class="header-anchor" href="#beta-3-0-0" aria-label="Permalink to “beta 3.0.0”">​</a></h2><p>事情太多忘记了</p><h2 id="cloud-relese-3-0-1" tabindex="-1">Cloud.Relese 3.0.1 <a class="header-anchor" href="#cloud-relese-3-0-1" aria-label="Permalink to “Cloud.Relese 3.0.1”">​</a></h2><h3 id="cloud-relese-3-0-1-0" tabindex="-1">Cloud.Relese 3.0.1.0 <a class="header-anchor" href="#cloud-relese-3-0-1-0" aria-label="Permalink to “Cloud.Relese 3.0.1.0”">​</a></h3><p>velocity的motd样式更加花里胡哨</p><p>whitelist前移到login，使用了whitelist4qq和mirai来实现在群内加白名单的效果</p><p>宣传更多了</p><p>tab样式进行了重写，使用十六进制颜色来上色</p><p>增加了职位标签</p><p>称号条件变更，见群公告</p><p>权限组调整，共有两条（毫不相关的）路线，一条作为管理权限，一条作为登录时长</p><p>使用了sunlight来变更职位标签，同时实现了签到和登录时长升级</p><p>default权限组进行了部分调整，可以在redt进行快速切服操作了（已移除。由于执行velocity命令的优先级<strong>大于所有插件</strong>且部分用户不受影响，该功能已废弃。预计在未来还会添加回来）</p><p>发包限制被完全解除</p><p>修改了更新文档的排版</p><p>有什么忘记的踢我一脚</p><pre><code>他妈的，每次开发文档都是我来写，你们没有一个会帮我的？（恼 -white_phosphor/huxk
</code></pre><blockquote><p><s>下一阶段打算恢复原来的sr，还有什么巴拉巴拉的不要等着我催你们写，自己想到什么加上去就好了，反正我也只是个苦逼打工人快乐程序员给你们来实现代码效果的而已</s></p></blockquote><blockquote><p><s>还有，他妈的能不能不要让我凑那么多字数？很累欸一点也不累，太轻松了</s></p></blockquote><h3 id="cloud-relese-3-0-1-1" tabindex="-1">Cloud.Relese 3.0.1.1 <a class="header-anchor" href="#cloud-relese-3-0-1-1" aria-label="Permalink to “Cloud.Relese 3.0.1.1”">​</a></h3><p>修复了登陆服务器输入密码错误导致显示指令刷屏的问题</p><p>更换了redt的皮肤插件至fabrictailor，从此支持自定义网址皮肤</p><p>准备迁移服务器</p><p><strong>修复了CSL数据库失效导致玩家无法登录的问题（突发事件）</strong></p><p>修复了由于IP地址被错误记录而导致无法注册的问题</p><p>清理了lg数据库，创建了lg数据库归档2022-11-13</p><p>入服申请引入了问卷没实装</p><p>清理了lg数据库，创建了lg数据库归档2023-1-5</p><p>移除了Herobrine</p><h2 id="local-relese-3-1-0-0" tabindex="-1"><a href="http://Local.Relese" target="_blank" rel="noreferrer">Local.Relese</a> 3.1.0.0 <a class="header-anchor" href="#local-relese-3-1-0-0" aria-label="Permalink to “Local.Relese 3.1.0.0”">​</a></h2><p>迁移服务器至本地（我家的主机），更换配置为64GRAM</p><p>迁移login，redt以及velocity全部至主机</p><p>修复了由于tencentCDB（腾讯云数据库）无法连接导致无法进行数据同步的问题，更换luckperms数据库存储方式为MariaDB</p><p>修复了由于mirai内核过老导致无法登录qq机器人的问题</p><p>更换登录服主城</p><p>lg数据库归档</p><h2 id="local-relese-3-1-0-1" tabindex="-1"><a href="http://Local.Relese" target="_blank" rel="noreferrer">Local.Relese</a> 3.1.0.1 <a class="header-anchor" href="#local-relese-3-1-0-1" aria-label="Permalink to “Local.Relese 3.1.0.1”">​</a></h2><p>采用邮箱来申请白名单（因为mirai无法登陆qq）</p><p>velocity上增加ranketify</p><p>写了个简单的邮箱验证</p><p>增加了creative，testpaper，testserver，cardboard，highpurpur等子服务器，最大性能利用cpu算力</p><p>修改chatbridge的聊天颜色</p><p>接入cqhttpbot</p><p>升级了mcsm增加花里胡哨的主题</p><p>可能还有别的忘记了</p><p>最后就是经典保留项目 lg和服务器数据归档（保留节目）</p><p>--</p><p>下一阶段的开发目标</p><p>使redt设计性能达到30人，最大性能达到50人</p><p>优化链接 使得链接更加流畅</p><p>如果可以的话，试着开一个经典红白风格的服务器 (完成了，但是rw不在了。)</p><p>如果可以的话，使用velocity的modern方式</p><p>把redwhite叫回来(不可能)</p><h2 id="local-relese-3-2" tabindex="-1"><a href="http://Local.Relese" target="_blank" rel="noreferrer">Local.Relese</a> 3.2 <a class="header-anchor" href="#local-relese-3-2" aria-label="Permalink to “Local.Relese 3.2”">​</a></h2><p>更新服务端内核为leaves(同时我也是leaves的文档维护者之一)</p><p>替换ledger为coreprotect</p><p>替换datapack为ASB，TrMenu和Trchat</p><p>更新default,helper和administrator权限组</p><p>更新菜单，聊天样式</p><p>更换velocity转发方式为modern</p><p>更新EmailWhiteList</p><p>写了个小网站</p><p>关闭timings，关闭ambient生成，怪物生成遍历尝试tick改为20tick</p><p>把redwhite拉回管理群潜水</p><p>更新到1.20.1</p><h2 id="local-relese-3-3" tabindex="-1"><a href="http://Local.Relese" target="_blank" rel="noreferrer">Local.Relese</a> 3.3 <a class="header-anchor" href="#local-relese-3-3" aria-label="Permalink to “Local.Relese 3.3”">​</a></h2><p>更新leaves</p><p>更新，维护，探索新功能......</p><p>网站搭建完毕</p><p>写了个船新白名单并挂载到网页</p><p>生成了个平面地图挂到网页</p><p>chatbridgeRW特供版（当然写的不咋地）</p><p>计划给网站迭代出更多花里胡哨的功能</p><h2 id="local-relese-3-4" tabindex="-1"><a href="http://Local.Relese" target="_blank" rel="noreferrer">Local.Relese</a> 3.4 <a class="header-anchor" href="#local-relese-3-4" aria-label="Permalink to “Local.Relese 3.4”">​</a></h2><p>添加回sunlight插件<br> 修复trmenu插件</p><p>加入富饶之域</p><p>计划给网页添加更多功能<br> 计划开发插件</p><p><strong>正式和Moreong工作室合并成立RMS。</strong></p><h1 id="第三世代" tabindex="-1">第三世代 <a class="header-anchor" href="#第三世代" aria-label="Permalink to “第三世代”">​</a></h1><h2 id="distributed-4-0" tabindex="-1">Distributed 4.0 <a class="header-anchor" href="#distributed-4-0" aria-label="Permalink to “Distributed 4.0”">​</a></h2><p>各位好，元旦快乐。本次大咕特咕了以下内容:</p><p>(测。看我之前自己写的开发日志真的是好羞耻啊( )</p><ol><li><p>继续咕咕咕网页</p></li><li><p>成功实现群组更换核心核心重组网</p></li><li><p>huxk在跨年夜被不知名的3位管理成员超市</p></li><li><p>RPG服务器开始初步搭建（先咕完2024年）</p></li><li><p><s>吗的真是</s></p></li><li><p>咕咕咕，咕咕咕咕，咕咕咕咕咕咕咕，咕！（大家好，我叫木白，带来一个好消息，唔！（被捉住了））</p></li></ol><h2 id="local-beta-4-1" tabindex="-1">Local.Beta 4.1 <a class="header-anchor" href="#local-beta-4-1" aria-label="Permalink to “Local.Beta 4.1”">​</a></h2><p>各位好。新春快乐。</p><p>更新内容：</p><h3 id="我们成功爆肝一星期写出了底层。包括" tabindex="-1">我们成功爆肝一星期写出了底层。包括： <a class="header-anchor" href="#我们成功爆肝一星期写出了底层。包括" aria-label="Permalink to “我们成功爆肝一星期写出了底层。包括：”">​</a></h3><ol><li><p>基于plotsquared的地皮世界</p></li><li><p>基于iris world gen的城镇世界</p></li><li><p>基于dynamicshop的动态商店</p></li><li><p>基于trmenu的菜单</p></li><li><p>基于typewriter的基础对话</p></li><li><p>基于mmo三件套的RPG基础内容</p></li><li><p>基于playertitle的玩家称号</p></li><li><p>基于CMI而非sunlight的基础权限管理</p></li><li><p>基于trchat的聊天样式</p></li></ol><h3 id="网页全面重写-未上线" tabindex="-1">网页全面重写（未上线） <a class="header-anchor" href="#网页全面重写-未上线" aria-label="Permalink to “网页全面重写（未上线）”">​</a></h3><h3 id="服务器重新组网合并" tabindex="-1">服务器重新组网合并 <a class="header-anchor" href="#服务器重新组网合并" aria-label="Permalink to “服务器重新组网合并”">​</a></h3><h3 id="咕咕。" tabindex="-1"><s>咕咕。</s> <a class="header-anchor" href="#咕咕。" aria-label="Permalink to “咕咕。”">​</a></h3><p>接下来会做的</p><ol><li><p>扩充游戏玩法。</p></li><li><p>开放地牢</p></li><li><p>开放任务大厅</p></li><li><p>开放人物任务</p></li><li><p>更炫酷的初始加入动画</p></li><li><p>更多的装备武器工具</p></li><li><p>更多的彩蛋</p></li><li><p><s>咕咕。</s></p></li></ol><h1 id="re一周目" tabindex="-1">Re一周目 <a class="header-anchor" href="#re一周目" aria-label="Permalink to “Re一周目”">​</a></h1><h2 id="beta-1-0" tabindex="-1">beta 1.0 <a class="header-anchor" href="#beta-1-0" aria-label="Permalink to “beta 1.0”">​</a></h2><ol><li>构建了一周目的大体框架</li></ol><h2 id="beta-1-1" tabindex="-1">beta 1.1 <a class="header-anchor" href="#beta-1-1" aria-label="Permalink to “beta 1.1”">​</a></h2><ol><li><p>加入了公会系统</p></li><li><p>加入了领地，并和公会系统绑定</p></li><li><p>加入抽奖箱，可以抽出酒品配方线索</p></li><li><p>预计beta1.2将加入摸金子服务器</p></li></ol><h2 id="beta-1-1-1-hyacinthus" tabindex="-1">beta 1.1.1 Hyacinthus <a class="header-anchor" href="#beta-1-1-1-hyacinthus" aria-label="Permalink to “beta 1.1.1 Hyacinthus”">​</a></h2><h3 id="游戏体验优化" tabindex="-1">游戏体验优化 <a class="header-anchor" href="#游戏体验优化" aria-label="Permalink to “游戏体验优化”">​</a></h3><ol><li><p>增添新的网络节点：上海腾讯云（十分感谢各位的赞助（跪））</p></li><li><p>增添新的web服务设施：资源包提供，官网，文档，服务器监视器</p></li><li><p>网络拓补结构优化，尝试加入底层架构的QUIC协议支持</p></li><li><p>其他漏洞修复和细节修正</p></li></ol><h3 id="服务器内容更新" tabindex="-1">服务器内容更新 <a class="header-anchor" href="#服务器内容更新" aria-label="Permalink to “服务器内容更新”">​</a></h3><ol><li><p>增加了月饼数据包，修正了初版的小问题</p></li><li><p>中秋节快乐，一起来吃月饼吗~</p></li><li><p><s>古咕顾！古咕顾！古咕顾！古咕顾！古咕顾！古咕顾！古咕顾！古咕顾！古咕顾！古咕顾！古咕顾！古咕顾！古咕顾！古咕顾！</s></p></li></ol>`,210)])])}const k=e(i,[["render",p]]);export{s as __pageData,k as default};
